const body = $json.body || $json || {};
const payload = body.payload || body;
const phone = body.phone || payload.phone || payload.from || payload.contact?.phone_number || payload.body?.phone || '';
if (phone && !/^\+?[0-9][0-9\s().-]{6,}$/.test(String(phone))) throw new Error('invalid phone for CRIS QA shadow');
const runKey = String(body.run_key || body.run_id || `cris-qa-shadow-${Date.now()}`);
return [{ json: { run_id: body.run_id || null, run_key: runKey, case_id: body.case_id || null, phone, conversation_id: body.conversation_id || payload.conversation_id || null, message_type: body.message_type || payload.kind || payload.event || 'shadow_payload', payload } }];
